    default := datetime_current();
  }
   target_name: str;
   change: str;
   multi target_name: str;
   multi change: str;
}

type Person {
  required name: str;

   trigger log_insert after insert for each do (
   trigger log_insert after insert for all do (
    insert Log {
      action := 'insert',
      target_name :=  __new__ .name
    }
